import{_ as t,o,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"Troubleshooting: YouTube Publishing","description":"Fix OAuth, metadata, and YouTube upload failures.","frontmatter":{"title":"Troubleshooting: YouTube Publishing","description":"Fix OAuth, metadata, and YouTube upload failures."},"headers":[],"relativePath":"support/troubleshooting_publishing.md","filePath":"support/troubleshooting_publishing.md"}'),n={name:"support/troubleshooting_publishing.md"};function s(r,e,l,u,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting-youtube-publishing" tabindex="-1">Troubleshooting: YouTube Publishing <a class="header-anchor" href="#troubleshooting-youtube-publishing" aria-label="Permalink to &quot;Troubleshooting: YouTube Publishing&quot;">​</a></h1><h2 id="_1-upload-failed-immediately" tabindex="-1">1. Upload Failed Immediately <a class="header-anchor" href="#_1-upload-failed-immediately" aria-label="Permalink to &quot;1. Upload Failed Immediately&quot;">​</a></h2><p><strong>Symptom:</strong> You click &quot;Publish to YouTube&quot;, and it fails instantly or offline token refresh fails. <strong>Cause:</strong> Your Google OAuth token has expired or the permissions were revoked. Note that while background workers will now attempt to automatically refresh expired tokens, older connected accounts might still fail if they lack the offline access scope. <strong>Solution:</strong></p><ol><li>Navigate to the <strong>Integrations</strong> page.</li><li>Click <strong>Disconnect YouTube</strong>.</li><li>Click <strong>Connect YouTube</strong> and re-approve the requested permissions (specifically the &quot;Manage your YouTube videos&quot; scope). This reconnect is necessary for old accounts to ensure the system can fetch a new refresh token.</li></ol><h2 id="_2-quota-exceeded-403-error" tabindex="-1">2. Quota Exceeded (403 Error) <a class="header-anchor" href="#_2-quota-exceeded-403-error" aria-label="Permalink to &quot;2. Quota Exceeded (403 Error)&quot;">​</a></h2><p><strong>Symptom:</strong> The upload fails with a &quot;Quota Exceeded&quot; warning. <strong>Cause:</strong> YouTube enforces strict daily upload API quotas, especially for newer channels (often limiting to 6-10 videos per day). <strong>Solution:</strong> You have hit YouTube&#39;s API limit. You must wait 24 hours for the quota to reset at midnight Pacific Time. Alternatively, download your video using the Export Modal and upload it manually via the YouTube website.</p><h2 id="_3-playlist-not-found" tabindex="-1">3. Playlist Not Found <a class="header-anchor" href="#_3-playlist-not-found" aria-label="Permalink to &quot;3. Playlist Not Found&quot;">​</a></h2><p><strong>Symptom:</strong> The video uploads successfully, but fails to add to your configured playlist. <strong>Cause:</strong> The playlist ID saved in your Project Settings was deleted on YouTube, or it belongs to a different YouTube channel than the one you authenticated with. <strong>Solution:</strong> Open the Project Settings modal and update the Playlist Sync ID to a valid playlist owned by the connected channel.</p><h2 id="_4-metadata-editor-changes-discarded" tabindex="-1">4. Metadata Editor Changes Discarded <a class="header-anchor" href="#_4-metadata-editor-changes-discarded" aria-label="Permalink to &quot;4. Metadata Editor Changes Discarded&quot;">​</a></h2><p><strong>Symptom:</strong> You edit the YouTube title/description, but the changes aren&#39;t saved to the final upload. <strong>Cause:</strong> You may have closed the Publish Modal without clicking <strong>Approve &amp; Save</strong>. <strong>Solution:</strong> Ensure you click the primary green button at the bottom of the modal to lock in your changes before the publisher agent executes the upload.</p>',10)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
